#include <bits/stdc++.h>
using namespace std;

#define int long long
#define endl '\n'

int a[600005],p[600005];

signed main() {
    int tt;
    cin >> tt;
    while(tt--) {
        int n;
        cin >> n;
        for(int i = 0 ; i < 3*n ; i++) {
            cin >> a[i];
        }
        sort(a,a+3*n,greater<int>());
        for(int i = 0 ; i < 3*n ; i++) {
            p[i + 1] = p[i] + a[i];
        }
        auto get = [&] (int i,int m) {
            int j = i + 2*m;
            int k = 3*n - 2*i - m;
            return 2*p[i] + p[j] + 3*p[k];
        };
        int Ans = 0;
        for(int i = 0 ; i <= n ; i++) {
            int start = 0;
            int end = n - i - 1;
            int ans = 0;
            while (start <= end) {
                int mid = start + (end - start) / 2;
                int d = a[i + 2*mid] + a[i + 2*mid + 1] - 3*a[3*n - 2*i-mid - 1];
                if(d >= 0) {
                    ans = mid + 1;
                    start = mid + 1;
                } 
                else {
                    end = mid - 1;
                }
            }
            Ans = max(Ans, get(i,ans));
            if(ans > 0) {
                Ans = max(Ans,get(i,ans-1));
            }
            if(ans < n - i) {
                Ans = max(Ans,get(i,ans+1));
            }
        }
        cout << Ans << '\n';
    }
    return 0;
}
